let COLD=["290100010000","","","",""]
let TICK=["260100060001000101de7fa872c3f9fd6911011f0016000c0002013a000531323a33350e00de7fa872c3f9fd699add2265513f5d3525bee35153077969813c916ddcbe2e35aca2ab53871b491f4a96473503ac63039ba3986476417948b0120f40b72de35d0461440311c8e7477f9b264f352fe749bf6f035a3d71061c55718e2506f2935ac16c78696f3f8d44231ad62eefb61d0f"]
